<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Filled CIF DOCX Preview</title>
<style>body{margin:0;background:#dfe7e9;font:8px Arial,sans-serif;color:#111}.doc{box-sizing:border-box;width:330mm;min-height:215.9mm;margin:18px auto;background:#fff;padding:7.62mm;box-shadow:0 2px 12px #0003}.cif-page{box-sizing:border-box;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12.5mm;width:100%;min-height:200.66mm;page-break-after:always}.cif-page:last-child{page-break-after:auto}.cif-column{min-width:0}.cif-header{border-bottom:1px solid #111;margin-bottom:5px;padding-bottom:4px}.cif-header-brand{display:flex;align-items:center;gap:6px;text-align:center;font-size:7px}.cif-header-brand>div{flex:1}.cif-logo{width:28px;height:28px;object-fit:contain}.cif-header-code{display:grid;grid-template-columns:1fr 1fr;border:1px solid #111;font-size:7px;margin-top:4px}.cif-header-code div{border:1px solid #111;padding:2px}.cif-header h2{text-align:center;font-size:10px;margin:5px 0 0}.doc p{margin:1px 0;line-height:1.15;white-space:pre-wrap}.doc table{width:100%;border-collapse:collapse;margin:5px 0;table-layout:fixed;break-inside:avoid}.doc td{border:1px solid #111;padding:2px;vertical-align:top;min-height:16px;word-wrap:break-word}.doc .cif-column:last-child{display:flex;flex-direction:column}.doc .cif-column:last-child p:last-child{margin-top:auto}@media (max-width:900px){.doc{margin-left:0;margin-right:0}}@media print{.doc{margin:0;box-shadow:none}}</style></head>
